# 2) vmstat 한 줄을 읽고 무엇이 모자란지 가린다 (USE: 사용률·포화·오류)
line = "r=14 b=6 free_mb=310 si=120 so=240 us=35 sy=20 id=5 wa=40 cpus=8"
v = {k: float(x) for k, x in (p.split("=") for p in line.split())}
if v["r"] > v["cpus"]:
    print("CPU 포화: 실행 대기", int(v["r"]), "> 코어", int(v["cpus"]))
if v["si"] + v["so"] > 0:
    print("메모리 부족: 스왑 입출력", int(v["si"] + v["so"]), "KB/s")
if v["wa"] >= 20:
    print("디스크 대기:", int(v["wa"]), "% — 스토리지·경로부터 본다")
